<?php

namespace Tests\Unit\Carousel;

use App\Carousel\Overlay;
use App\Carousel\OverlaySchema;
use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\TestCase;

/**
 * Port of carousel-overlay.test.ts (server parts). `fixtures/overlay.json` was generated by the TS implementation
 * (`parseOverlayStrict`, `parseOverlayDocument`, `safeHref`, `normalizeSize`, `legacyLayers`, `slideDocument`, `legacyFields`).
 */
class OverlayTest extends TestCase
{
    private static function fixture(bool $assoc = false): mixed
    {
        return json_decode((string) file_get_contents(__DIR__.'/fixtures/overlay.json'), $assoc);
    }

    /** What the Svelte islands receive: the view model as JSON. */
    private static function wire(mixed $value): mixed
    {
        return json_decode(json_encode($value, JSON_THROW_ON_ERROR));
    }

    private static function wrap(array $layer, array $extra = []): string
    {
        return json_encode(['v' => 1, 'layers' => [$layer], ...$extra]);
    }

    private static function ok(string $raw): bool
    {
        return OverlaySchema::parseOverlayStrict($raw)['ok'];
    }

    // ---- fixtures from the TS implementation -------------------------------------------------------------------

    public static function overlayCases(): iterable
    {
        foreach (array_keys((array) self::fixture()->cases) as $name) {
            yield $name => [$name];
        }
    }

    #[DataProvider('overlayCases')]
    public function test_strict_and_tolerant_parsers_match_the_ts_implementation(string $name): void
    {
        $case = self::fixture()->cases->{$name};
        $raw = $name === 'oversize' ? '{"v":1,"layers":[],"pad":"'.str_repeat('x', 41000).'"}' : $case->raw;

        $strict = OverlaySchema::parseOverlayStrict($raw);
        $this->assertEquals($case->strict, self::wire($strict), "strict: {$name}");
        if ($strict['ok']) {
            $this->assertSame($case->strictSerialized, Overlay::serializeOverlay($strict['layers'], $strict['mobile']), "serialized: {$name}");
        }

        $document = OverlaySchema::parseOverlayDocument($raw);
        $this->assertEquals($case->document, self::wire($document), "document: {$name}");
        if ($document !== null) {
            $this->assertSame($case->documentSerialized, Overlay::serializeOverlay($document['layers'], $document['mobile']), "document serialized: {$name}");
        }
    }

    public function test_safe_href_and_image_src_match_the_ts_implementation(): void
    {
        foreach (self::fixture()->hrefs as $case) {
            $this->assertSame($case->href, Overlay::safeHref($case->input), 'href: '.json_encode($case->input));
            $this->assertSame($case->image, Overlay::safeImageSrc($case->input), 'image: '.json_encode($case->input));
        }
    }

    public function test_size_normalisation_matches_the_ts_implementation(): void
    {
        foreach (self::fixture()->sizes as $case) {
            $this->assertSame($case->out, Overlay::normalizeSize($case->kind, $case->size), "{$case->kind} ".json_encode($case->size));
        }
    }

    public function test_legacy_layers_and_fields_match_the_ts_implementation(): void
    {
        foreach (self::fixture(true)['legacy'] as $case) {
            $this->assertEquals($case['layers'], Overlay::legacyLayers($case['row']), json_encode($case['row'] ?? null));
        }
        foreach (self::fixture(true)['fields'] as $case) {
            $this->assertSame($case['out'], Overlay::legacyFields($case['layers']));
        }
    }

    public function test_slide_document_matches_the_ts_implementation(): void
    {
        foreach (self::fixture(true)['slideDocs'] as $case) {
            $this->assertEquals(
                json_decode(json_encode($case['doc'])),
                self::wire(OverlaySchema::slideDocument($case['row'])),
            );
        }
    }

    // ---- safeHref ----------------------------------------------------------------------------------------------

    public function test_safe_href_allows_paths_fragments_and_http_mailto_tel(): void
    {
        foreach (['/posts', '/a?b=1#c', '#top', 'https://sic.edu/x', 'http://a.test', 'mailto:a@b.test', 'tel:+63123'] as $url) {
            $this->assertSame($url, Overlay::safeHref($url));
        }
    }

    public function test_safe_href_blocks_script_capable_protocol_relative_and_malformed_urls(): void
    {
        foreach ([
            'javascript:alert(1)', ' JaVaScRiPt:alert(1)', "java\tscript:alert(1)", 'data:text/html,<script>', 'vbscript:x',
            '//evil.test', '/\\evil.test', 'posts', 'ftp://a.test', '', '   ', '/'.str_repeat('a', 600),
        ] as $url) {
            $this->assertNull(Overlay::safeHref($url), $url);
        }
        $this->assertNull(Overlay::safeHref(null));
    }

    public function test_image_sources_are_paths_or_http_only(): void
    {
        $this->assertSame('/storage/posts/inline/a.png', Overlay::safeImageSrc('/storage/posts/inline/a.png'));
        $this->assertSame('https://cdn.test/a.png', Overlay::safeImageSrc('https://cdn.test/a.png'));
        $this->assertNull(Overlay::safeImageSrc('mailto:a@b.test'));
        $this->assertNull(Overlay::safeImageSrc('#x'));
        $this->assertNull(Overlay::safeImageSrc('data:image/png;base64,AAAA'));
    }

    public function test_external_links_get_a_safe_rel(): void
    {
        $this->assertSame('noopener noreferrer', Overlay::relFor('https://a.test'));
        $this->assertNull(Overlay::relFor('/posts'));
    }

    // ---- parseOverlayStrict ------------------------------------------------------------------------------------

    public function test_strict_round_trips_every_layer_type(): void
    {
        $layers = [
            Overlay::defaultLayer('shape'),
            Overlay::defaultLayer('text'),
            Overlay::defaultLayer('badge'),
            Overlay::defaultLayer('button'),
            [...Overlay::defaultLayer('image'), 'src' => '/storage/posts/inline/logo.png', 'alt' => 'School seal'],
        ];
        $result = OverlaySchema::parseOverlayStrict(Overlay::serializeOverlay($layers));
        $this->assertEquals(['ok' => true, 'layers' => $layers, 'mobile' => null], $result);
    }

    public function test_strict_rejects_unknown_properties_bad_enums_and_out_of_range_geometry(): void
    {
        $base = Overlay::defaultLayer('text');
        foreach ([
            ['onclick' => 'x'], ['color' => '#ff0000'], ['size' => '99px'], ['x' => 150], ['w' => 0],
            ['id' => 'a b'], ['text' => ''], ['text' => str_repeat('x', 501)],
        ] as $change) {
            $this->assertFalse(self::ok(self::wrap([...$base, ...$change])), json_encode($change));
        }
        $this->assertFalse(self::ok(self::wrap(['type' => 'script', 'id' => 'a'])));
    }

    public function test_strict_rejects_unsafe_links_unsafe_image_sources_and_missing_alt_text(): void
    {
        $this->assertFalse(self::ok(self::wrap([...Overlay::defaultLayer('button'), 'href' => 'javascript:alert(1)'])));
        $this->assertFalse(self::ok(self::wrap([...Overlay::defaultLayer('image'), 'src' => 'data:image/png;base64,AA', 'alt' => 'x'])));
        $this->assertFalse(self::ok(self::wrap([...Overlay::defaultLayer('image'), 'src' => '/storage/a.png', 'alt' => ' '])));
    }

    public function test_strict_rejects_wrong_version_duplicate_ids_too_many_layers_and_oversize_or_invalid_json(): void
    {
        $this->assertFalse(self::ok(json_encode(['v' => 2, 'layers' => []])));
        $a = Overlay::defaultLayer('text');
        $this->assertFalse(self::ok(json_encode(['v' => 1, 'layers' => [$a, $a]])));
        $many = array_map(fn () => Overlay::defaultLayer('text'), range(0, Overlay::MAX_LAYERS));
        $this->assertFalse(self::ok(Overlay::serializeOverlay($many)));
        $this->assertFalse(self::ok('{not json'));
        $this->assertFalse(self::ok('{"v":1,"layers":[],"pad":"'.str_repeat('x', 41_000).'"}'));
    }

    public function test_strict_reports_the_first_problem_with_its_layer_number(): void
    {
        $result = OverlaySchema::parseOverlayStrict(json_encode(['v' => 1, 'layers' => [
            Overlay::defaultLayer('text'),
            [...Overlay::defaultLayer('badge'), 'text' => ''],
        ]]));
        $this->assertSame(['ok' => false, 'error' => 'Badges cannot be empty. (layer 2)'], $result);
    }

    public function test_strict_fills_defaults_and_rounds_geometry(): void
    {
        $shape = Overlay::defaultLayer('shape');
        unset($shape['rotation'], $shape['opacity']);
        $result = OverlaySchema::parseOverlayStrict(self::wrap([...$shape, 'x' => 1.23456]));
        $this->assertTrue($result['ok']);
        $this->assertSame(1.23, $result['layers'][0]['x']);
        $this->assertSame(0, $result['layers'][0]['rotation']);
        $this->assertSame(100, $result['layers'][0]['opacity']);
    }

    public function test_strict_keeps_html_as_plain_text(): void
    {
        $layer = [...Overlay::defaultLayer('text'), 'text' => '<img src=x onerror=alert(1)>'];
        $result = OverlaySchema::parseOverlayStrict(Overlay::serializeOverlay([$layer]));
        $this->assertSame('<img src=x onerror=alert(1)>', $result['layers'][0]['text']);
    }

    // ---- parseOverlay (tolerant) -------------------------------------------------------------------------------

    public function test_tolerant_read_is_null_for_missing_invalid_or_other_version_documents(): void
    {
        $this->assertNull(OverlaySchema::parseOverlay(null));
        $this->assertNull(OverlaySchema::parseOverlay(''));
        $this->assertNull(OverlaySchema::parseOverlay('nope'));
        $this->assertNull(OverlaySchema::parseOverlay('[]'));
        $this->assertNull(OverlaySchema::parseOverlay(json_encode(['v' => 9, 'layers' => []])));
    }

    public function test_an_explicit_empty_overlay_is_kept(): void
    {
        $this->assertSame([], OverlaySchema::parseOverlay(Overlay::serializeOverlay([])));
    }

    public function test_tolerant_read_drops_invalid_and_duplicate_layers_and_all_invalid_is_null(): void
    {
        $good = Overlay::defaultLayer('text');
        $raw = json_encode(['v' => 1, 'layers' => [$good, $good, ['type' => 'button', 'id' => 'b', 'href' => 'javascript:1']]]);
        $this->assertEquals([$good], OverlaySchema::parseOverlay($raw));
        $this->assertNull(OverlaySchema::parseOverlay(json_encode(['v' => 1, 'layers' => [['type' => 'nope']]])));
    }

    // ---- legacy conversion -------------------------------------------------------------------------------------

    public function test_legacy_conversion_builds_layers_that_validate(): void
    {
        $layers = Overlay::legacyLayers(['title' => 'Welcome', 'subtitle' => 'To SIC', 'linkUrl' => '/posts']);
        $this->assertSame(['text', 'text', 'button'], array_column($layers, 'type'));
        $this->assertTrue(self::ok(Overlay::serializeOverlay($layers)));
        $this->assertSame(['title' => 'Welcome', 'subtitle' => 'To SIC', 'linkUrl' => '/posts'], Overlay::legacyFields($layers));
    }

    public function test_legacy_conversion_skips_empty_fields_and_unsafe_links(): void
    {
        $this->assertSame([], Overlay::legacyLayers(['title' => ' ', 'subtitle' => null, 'linkUrl' => 'javascript:alert(1)']));
        $this->assertSame(['title' => null, 'subtitle' => null, 'linkUrl' => null], Overlay::legacyFields([]));
    }

    // ---- slideDocument -----------------------------------------------------------------------------------------

    public function test_slide_document_converts_a_legacy_row(): void
    {
        $legacy = ['overlay' => null, 'title' => 'Welcome', 'subtitle' => 'To SIC', 'linkUrl' => '/posts'];
        $doc = OverlaySchema::slideDocument($legacy);
        $this->assertNull($doc['mobile']);
        $this->assertCount(3, $doc['layers']);
        [$heading, $subtitle, $button] = $doc['layers'];
        $this->assertSame(['text', 'heading', 'Welcome', 6, 30, 60], [$heading['type'], $heading['role'], $heading['text'], $heading['x'], $heading['y'], $heading['w']]);
        $this->assertSame(['subtitle', 'To SIC', 56, 55, 'md', 'sans'], [$subtitle['role'], $subtitle['text'], $subtitle['y'], $subtitle['w'], $subtitle['size'], $subtitle['font']]);
        $this->assertSame(['button', 'Explore more', '/posts', 6, 74], [$button['type'], $button['label'], $button['href'], $button['x'], $button['y']]);
        $this->assertTrue(self::ok(Overlay::serializeOverlay($doc['layers'])));

        $this->assertCount(3, OverlaySchema::slideDocument([...$legacy, 'overlay' => '{"v":1,"layers":[{"type":"nope"}]}'])['layers']);
    }

    public function test_a_stored_overlay_wins_over_the_legacy_columns_even_without_layers(): void
    {
        $legacy = ['overlay' => null, 'title' => 'Welcome', 'subtitle' => 'To SIC', 'linkUrl' => '/posts'];
        $stored = Overlay::serializeOverlay([], ['focus' => ['x' => 20, 'y' => 30]]);
        $this->assertEquals(['layers' => [], 'mobile' => ['focus' => ['x' => 20, 'y' => 30]]], OverlaySchema::slideDocument([...$legacy, 'overlay' => $stored]));
        $this->assertSame([], OverlaySchema::slideDocument(['overlay' => null, 'title' => null, 'subtitle' => null, 'linkUrl' => null])['layers']);
    }

    // ---- readingOrder, type scale ------------------------------------------------------------------------------

    public function test_reading_order_sorts_top_to_bottom_then_left_to_right_and_keeps_array_position_as_z(): void
    {
        $text = fn (string $id, int $y, int $x) => [...Overlay::defaultLayer('text'), 'id' => $id, 'y' => $y, 'x' => $x];
        $order = Overlay::readingOrder([$text('a', 60, 5), $text('b', 10, 50), $text('c', 10, 5)]);
        $this->assertSame([['c', 3], ['b', 2], ['a', 1]], array_map(fn (array $i) => [$i['layer']['id'], $i['z']], $order));
    }

    public function test_every_kind_has_sm_md_lg_increasing_and_defaults_are_on_the_scale(): void
    {
        foreach (Overlay::TYPE_SCALE as $kind => $steps) {
            $this->assertSame(['sm', 'md', 'lg'], array_keys($steps));
            $this->assertLessThan($steps['md'], $steps['sm']);
            $this->assertLessThan($steps['lg'], $steps['md']);
            $this->assertGreaterThan(0, $steps[Overlay::DEFAULT_SIZE[$kind]]);
        }
    }

    public function test_legacy_sizes_map_to_the_nearest_step_per_element_kind(): void
    {
        foreach ([['button', '3xl', 'lg'], ['button', 'xs', 'sm'], ['heading', '2xl', 'md'], ['heading', 'xs', 'sm'], ['badge', 'xl', 'lg'],
            ['body', 'md', 'md'], ['subtitle', 'nope', 'md'], ['heading', 'lg', 'lg']] as [$kind, $size, $expected]) {
            $this->assertSame($expected, Overlay::normalizeSize($kind, $size), "{$kind} {$size}");
        }
    }

    public function test_old_format_documents_load_in_both_parsers_and_are_saved_in_the_new_form(): void
    {
        $raw = json_encode(['v' => 1, 'layers' => [[...Overlay::defaultLayer('button'), 'size' => '3xl'], [...Overlay::defaultLayer('text'), 'size' => '2xl']]]);
        $sizes = fn (array $layers) => array_column($layers, 'size');
        $this->assertSame(['lg', 'md'], $sizes(OverlaySchema::parseOverlay($raw)));
        $this->assertSame(['lg', 'md'], $sizes(OverlaySchema::parseOverlayStrict($raw)['layers']));
        $this->assertStringNotContainsString('3xl', Overlay::serializeOverlay(OverlaySchema::parseOverlay($raw)));
        $this->assertFalse(self::ok(json_encode(['v' => 1, 'layers' => [[...Overlay::defaultLayer('button'), 'size' => 'huge']]])));
    }

    // ---- phone overrides ---------------------------------------------------------------------------------------

    public function test_a_document_written_before_phone_overrides_serializes_byte_for_byte(): void
    {
        $stored = '{"v":1,"layers":[{"type":"text","id":"a","x":6,"y":36,"rotation":0,"opacity":100,"w":55,"role":"heading","text":"Hi","size":"lg","align":"left","color":"white","font":"serif"}]}';
        $result = OverlaySchema::parseOverlayStrict($stored);
        $this->assertNull($result['mobile']);
        $this->assertSame($stored, Overlay::serializeOverlay($result['layers'], $result['mobile']));
        $this->assertNull(OverlaySchema::parseOverlayDocument($stored)['mobile']);
    }

    public function test_per_layer_overrides_and_the_slide_focal_point_round_trip(): void
    {
        $layer = [...Overlay::defaultLayer('text'), 'mobile' => ['x' => 10.123, 'y' => 40, 'w' => 80, 'size' => 'md', 'hidden' => false]];
        $focus = ['focus' => ['x' => 30, 'y' => 70]];
        $result = OverlaySchema::parseOverlayStrict(Overlay::serializeOverlay([$layer], $focus));
        $this->assertEquals(['x' => 10.12, 'y' => 40, 'w' => 80, 'size' => 'md', 'hidden' => false], $result['layers'][0]['mobile']);
        $this->assertEquals($focus, $result['mobile']);
        $this->assertEquals($focus, OverlaySchema::parseOverlayDocument(Overlay::serializeOverlay([$layer], $focus))['mobile']);
    }

    public function test_a_hide_only_override_needs_no_position(): void
    {
        $base = Overlay::defaultLayer('text');
        $this->assertTrue(self::ok(self::wrap([...$base, 'mobile' => ['hidden' => true]])));
        $this->assertTrue(self::ok(self::wrap([...$base, 'mobile' => ['size' => 'sm']])));
    }

    public function test_an_empty_override_stays_a_json_object(): void
    {
        $result = OverlaySchema::parseOverlayStrict('{"v":1,"layers":['.json_encode([...Overlay::defaultLayer('text'), 'mobile' => new \stdClass]).']}');
        $this->assertStringContainsString('"mobile":{}', Overlay::serializeOverlay($result['layers']));
    }

    public function test_rejects_out_of_bounds_lone_x_or_y_unknown_and_non_token_values(): void
    {
        $bad = fn (array $mobile) => self::ok(self::wrap([...Overlay::defaultLayer('text'), 'mobile' => $mobile]));
        foreach ([
            ['x' => 101, 'y' => 0], ['x' => -1, 'y' => 0], ['x' => 0, 'y' => 150], ['x' => 0, 'y' => 0, 'w' => 0], ['x' => 0, 'y' => 0, 'w' => 101],
            ['x' => 0, 'y' => 0, 'h' => 0], ['x' => 10], ['y' => 10], ['size' => '3xl'], ['size' => '22px'], ['hidden' => 'yes'], ['color' => 'white'],
        ] as $mobile) {
            $this->assertFalse($bad($mobile), json_encode($mobile));
        }
        $this->assertTrue($bad(['x' => 0, 'y' => 0, 'w' => 50, 'h' => 50]));
    }

    public function test_rejects_out_of_bounds_focal_points_and_unknown_slide_settings(): void
    {
        $slide = fn (array $mobile) => self::ok(self::wrap(Overlay::defaultLayer('text'), ['mobile' => $mobile]));
        $this->assertFalse($slide(['focus' => ['x' => 101, 'y' => 0]]));
        $this->assertFalse($slide(['focus' => ['x' => 50]]));
        $this->assertFalse($slide(['focus' => ['x' => 50, 'y' => 50], 'extra' => 1]));
        $this->assertTrue($slide(['focus' => ['x' => 0, 'y' => 100]]));
    }

    public function test_the_tolerant_read_keeps_a_layer_whose_phone_overrides_are_invalid_without_them(): void
    {
        $base = Overlay::defaultLayer('text');
        $raw = self::wrap([...$base, 'mobile' => ['x' => 500, 'y' => 0]], ['mobile' => ['focus' => ['x' => 900, 'y' => 0]]]);
        $doc = OverlaySchema::parseOverlayDocument($raw);
        $this->assertEquals([$base], $doc['layers']);
        $this->assertNull($doc['mobile']);
    }
}
